#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b;
    cin >> a >> b;

    long long g = std::gcd(a, b);
    __int128 lcm = (__int128)(a / g) * b;
    __int128 nextA = a, nextB = b;
    __int128 previous = 0;
    __int128 dasha = 0, masha = 0;

    while (true) {
        if (nextA < nextB) {
            dasha += nextA - previous;
            previous = nextA;
            nextA += a;
        } else if (nextB < nextA) {
            masha += nextB - previous;
            previous = nextB;
            nextB += b;
        } else {
            if (a > b)
                dasha += nextA - previous;
            else
                masha += nextA - previous;

            if (nextA == lcm)
                break;

            previous = nextA;
            nextA += a;
            nextB += b;
        }
    }

    if (dasha > masha)
        cout << "Dasha";
    else if (masha > dasha)
        cout << "Masha";
    else
        cout << "Equal";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using i128 = __int128_t;
using int64 = long long;

i128 score(int64 n, int64 limit) {
    i128 count = n - 1;
    if (count <= limit)
        return count * (count + 1) / 2;
    return i128(limit) * (limit + 1) / 2
         + (count - limit) * limit;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 a, b;
    cin >> a >> b;

    int64 g = gcd(a, b);
    int64 A = a / g;
    int64 B = b / g;

    i128 dasha = score(B, A);
    i128 masha = score(A, B);
    i128 common = min(A, B);

    if (a > b)
        dasha += common;
    else
        masha += common;

    if (dasha > masha)
        cout << "Dasha";
    else if (masha > dasha)
        cout << "Masha";
    else
        cout << "Equal";

    return 0;
}

