#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

i128 sumMin(i128 cap, i128 n) {
    if (n <= 0) return 0;
    if (n <= cap) return n * (n + 1) / 2;
    return cap * (cap + 1) / 2 + (n - cap) * cap;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 a, b;
    cin >> a >> b;

    int64 g = std::gcd(a, b);
    i128 A = a / g;
    i128 B = b / g;

    i128 dash = sumMin(A, B - 1);
    i128 mash = sumMin(B, A - 1);
    i128 common = min(A, B);

    if (A > B)
        dash += common;
    else
        mash += common;

    if (dash > mash)
        cout << "Dasha";
    else if (mash > dash)
        cout << "Masha";
    else
        cout << "Equal";

    return 0;
}

